import unicodedata


def slugify(text: str, max_length: int | None = None) -> str:
    normalized = unicodedata.normalize("NFKD", text)
    stripped = "".join(
        ch for ch in normalized if not unicodedata.combining(ch)
    )
    lowered = stripped.lower()
    result = []
    prev_sep = False
    for ch in lowered:
        if ch.isascii() and ch.isalnum():
            result.append(ch)
            prev_sep = False
        else:
            if not prev_sep:
                result.append("-")
                prev_sep = True
    slug = "".join(result).strip("-")
    if max_length is not None:
        slug = slug[:max_length].rstrip("-")
    return slug

from slugify import slugify


def test_basic():
    assert slugify("Hello World") == "hello-world"


def test_accents():
    assert slugify("Crème Brûlée") == "creme-brulee"


def test_separators():
    assert slugify("  Hello___World!!  ") == "hello-world"


def test_tabs_newlines():
    assert slugify("a\tb\nc") == "a-b-c"


def test_non_ascii_separator():
    assert slugify("aßb") == "a-b"
    assert slugify("a日本b") == "a-b"


def test_strip_hyphens():
    assert slugify("---Hello---") == "hello"


def test_max_length():
    assert slugify("hello world", max_length=8) == "hello"
    assert slugify("hello world", max_length=0) == ""
    assert slugify("hello world", max_length=5) == "hello"


def test_empty():
    assert slugify("") == ""
    assert slugify("   ") == ""
    assert slugify("!!!") == ""


def test_only_separators_after_nfkd():
    assert slugify("日本") == ""
